macro_rules! deps {
    () => {
        Shorten!();
        FunctionalSequence!();
        Lengthen!();
        ArrayLength!();
        GenericSequence!();
        Split!();
        Concat!();
    };
}

macro_rules! GenericArray {
    () => {
        deps!();
        # [doc = " Struct representing a generic array - `GenericArray<T, N>` works like `[T; N]`"] # [doc = ""] # [doc = " For how to implement [`Copy`] on structs using a generic-length `GenericArray` internally, see"] # [doc = " the docs for [`ArrayLength::ArrayType`]."] # [doc = ""] # [doc = " # Usage Notes"] # [doc = ""] # [doc = " ### Initialization"] # [doc = ""] # [doc = " Initialization of known-length `GenericArray`s can be done via the [`arr![]`](arr!) macro,"] # [doc = " or [`from_array`](GenericArray::from_array)/[`from_slice`](GenericArray::from_slice)."] # [doc = ""] # [doc = " For generic arrays of unknown/generic length, several safe methods are included to initialize"] # [doc = " them, such as the [`GenericSequence::generate`] method:"] # [doc = ""] # [doc = " ```rust"] # [doc = " use generic_array::{GenericArray, sequence::GenericSequence, typenum, arr};"] # [doc = ""] # [doc = " let evens: GenericArray<i32, typenum::U4> ="] # [doc = "            GenericArray::generate(|i: usize| i as i32 * 2);"] # [doc = ""] # [doc = " assert_eq!(evens, arr![0, 2, 4, 6]);"] # [doc = " ```"] # [doc = ""] # [doc = " Furthermore, [`FromIterator`] and [`try_from_iter`](GenericArray::try_from_iter) exist to construct them"] # [doc = " from iterators, but will panic/fail if not given exactly the correct number of elements."] # [doc = ""] # [doc = " ### Utilities"] # [doc = ""] # [doc = " The [`GenericSequence`], [`FunctionalSequence`], [`Lengthen`], [`Shorten`], [`Split`], and [`Concat`] traits implement"] # [doc = " some common operations on generic arrays."] # [doc = ""] # [doc = " ### Optimizations"] # [doc = ""] # [doc = " Prefer to use the slice iterators like `.iter()`/`.iter_mut()` rather than by-value [`IntoIterator`]/[`GenericArrayIter`] if you can."] # [doc = " Slices optimize better. Using the [`FunctionalSequence`] methods also optimize well."] # [doc = ""] # [doc = " # How it works"] # [doc = ""] # [doc = " The `typenum` crate uses Rust's type system to define binary integers as nested types,"] # [doc = " and allows for operations which can be applied to those type-numbers, such as `Add`, `Sub`, etc."] # [doc = ""] # [doc = " e.g. `6` would be `UInt<UInt<UInt<UTerm, B1>, B1>, B0>`"] # [doc = ""] # [doc = " `generic-array` uses this nested type to recursively allocate contiguous elements, statically."] # [doc = " The [`ArrayLength`] trait is implemented on `UInt<N, B0>`, `UInt<N, B1>` and `UTerm`,"] # [doc = " which correspond to even, odd and zero numeric values, respectively."] # [doc = " Together, these three cover all cases of `Unsigned` integers from `typenum`."] # [doc = " For `UInt<N, B0>` and `UInt<N, B1>`, it peels away the highest binary digit and"] # [doc = " builds up a recursive structure that looks almost like a binary tree."] # [doc = " Then, within `GenericArray`, the recursive structure is reinterpreted as a contiguous"] # [doc = " chunk of memory and allowing access to it as a slice."] # [doc = ""] # [doc = " <details>"] # [doc = " <summary><strong>Expand for internal structure demonstration</strong></summary>"] # [doc = ""] # [doc = " For example, `GenericArray<T, U6>` more or less expands to (at compile time):"] # [doc = ""] # [doc = " ```ignore"] # [doc = " GenericArray {"] # [doc = "     // 6 = UInt<UInt<UInt<UTerm, B1>, B1>, B0>"] # [doc = "     data: EvenData {"] # [doc = "         // 3 = UInt<UInt<UTerm, B1>, B1>"] # [doc = "         left: OddData {"] # [doc = "             // 1 = UInt<UTerm, B1>"] # [doc = "             left: OddData {"] # [doc = "                 left: (),  // UTerm"] # [doc = "                 right: (), // UTerm"] # [doc = "                 data: T,   // Element 0"] # [doc = "             },"] # [doc = "             // 1 = UInt<UTerm, B1>"] # [doc = "             right: OddData {"] # [doc = "                 left: (),  // UTerm"] # [doc = "                 right: (), // UTerm"] # [doc = "                 data: T,   // Element 1"] # [doc = "             },"] # [doc = "             data: T        // Element 2"] # [doc = "         },"] # [doc = "         // 3 = UInt<UInt<UTerm, B1>, B1>"] # [doc = "         right: OddData {"] # [doc = "             // 1 = UInt<UTerm, B1>"] # [doc = "             left: OddData {"] # [doc = "                 left: (),  // UTerm"] # [doc = "                 right: (), // UTerm"] # [doc = "                 data: T,   // Element 3"] # [doc = "             },"] # [doc = "             // 1 = UInt<UTerm, B1>"] # [doc = "             right: OddData {"] # [doc = "                 left: (),  // UTerm"] # [doc = "                 right: (), // UTerm"] # [doc = "                 data: T,   // Element 4"] # [doc = "             },"] # [doc = "             data: T        // Element 5"] # [doc = "         }"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " This has the added benefit of only being `log2(N)` deep, which is important for things like `Drop`"] # [doc = " to avoid stack overflows, since we can't implement `Drop` manually."] # [doc = ""] # [doc = " Then, we take the contiguous block of data and cast it to `*const T` or `*mut T` and use it as a slice:"] # [doc = ""] # [doc = " ```ignore"] # [doc = " unsafe {"] # [doc = "     slice::from_raw_parts("] # [doc = "         self as *const GenericArray<T, N> as *const T,"] # [doc = "         <N as Unsigned>::USIZE"] # [doc = "     )"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " </details>"] # [repr (transparent)] pub struct GenericArray < T , N : ArrayLength > { # [allow (dead_code)] data : N :: ArrayType < T > , }
    };
}

GenericArray!()